-- 225 (17/11/2026, lô 55): « DELF B1 · Đề 4 », phần ĐỌC viết lại khó hơn (văn bản dài hơn, câu hỏi về hàm ý).
-- Sinh bởi scripts/nhap/lo55_kho.mjs --cap B1 --de 4. Sửa thẳng, giữ id bài và id câu (cập nhật theo ord). Chạy lại an toàn.
-- lo22mvemxfqi025
update public.exercises set consigne = '<p>Vous cherchez une activité pour votre neveu de 14 ans. Lisez les annonces et répondez aux questions.</p>', reading_text = '<p><strong>A. Club de robotique « Les Bricodeurs »</strong> : le mercredi de 14 h à 16 h, pour les 12-16 ans. Les jeunes construisent et programment de petits robots, puis les présentent à un concours régional en mai. 80 € l''année, matériel fourni. Aucune connaissance en informatique n''est exigée, mais une présence régulière est indispensable.</p><p><strong>B. Atelier photo au smartphone</strong> : dix séances le samedi de 10 h à 12 h. Apprenez à cadrer, à jouer avec la lumière et à retoucher vos images. Chaque participant vient avec son propre téléphone. 60 € le cycle. Les meilleures photos seront exposées à la médiathèque en fin d''année. À partir de 15 ans.</p><p><strong>C. Théâtre d''improvisation</strong> : le mardi de 18 h à 19 h 30, groupes de dix jeunes au maximum pour que chacun ait le temps de jouer. Spectacle en juin devant les familles. 150 € l''année, possibilité de payer en trois fois. Une séance d''essai gratuite est proposée en septembre.</p><p><strong>D. Randonnée nature</strong> : un dimanche par mois, départ à 8 h devant la mairie. Gratuit, mais inscription obligatoire la semaine précédente. Les téléphones sont rassemblés dans une boîte au départ et rendus au retour : une journée entière pour se déconnecter. Prévoir chaussures de marche et pique-nique. Mineurs accompagnés d''un adulte.</p><p><strong>E. Cours de guitare en ligne</strong> : des vidéos courtes et un professeur qui répond à vos questions par message sous 48 heures. Horaires libres, 15 € par mois, premier mois offert, sans engagement. Une guitare est nécessaire ; possibilité d''en louer une auprès de notre partenaire.</p>' where id = 'lo22mvemxfqi025';
update public.questions q set type = v.type, prompt = v.prompt, payload = v.payload, answer_key = v.answer_key, explanation = v.explanation
from (values
  (1, 'qcm', 'Votre neveu n''a pas de budget, et son père peut l''accompagner. Il choisit…', '{"options":["D","A","E"]}'::jsonb, '{"answer":0}'::jsonb, 'D: « Gratuit » và « Mineurs accompagnés d''un adulte ». E chỉ miễn phí tháng đầu (« premier mois offert »).'),
  (2, 'qcm', 'Il veut essayer avant de s''engager pour l''année, et il aime jouer devant un public. Il choisit…', '{"options":["B","E","C"]}'::jsonb, '{"answer":2}'::jsonb, 'C có « Une séance d''essai gratuite » và « Spectacle en juin devant les familles ».'),
  (3, 'qcm', 'Quelle activité lui est interdite à cause de son âge ?', '{"options":["A","D","B"]}'::jsonb, '{"answer":2}'::jsonb, 'Cháu 14 tuổi, còn B ghi « À partir de 15 ans ».'),
  (4, 'qcm', 'Il aimerait participer à une compétition. Il choisit…', '{"options":["A","B","C"]}'::jsonb, '{"answer":0}'::jsonb, 'A: « les présentent à un concours régional en mai ». B chỉ triển lãm ảnh, không thi.'),
  (5, 'qcm', 'Pour le cours de guitare, un jeune qui n''a pas d''instrument…', '{"options":["ne peut pas s''inscrire.","en reçoit une le premier mois.","peut en louer une."]}'::jsonb, '{"answer":2}'::jsonb, '« possibilité d''en louer une auprès de notre partenaire ».')
) as v(ord, type, prompt, payload, answer_key, explanation)
where q.exercise_id = 'lo22mvemxfqi025' and q.ord = v.ord;

-- lo22mvemxfqj026
update public.exercises set consigne = '<p>Lisez l''article puis répondez aux questions.</p>', reading_text = '<p><strong>Réseaux sociaux avant 15 ans : une interdiction votée… puis bloquée</strong></p><p>Le 21 juillet 2026, au terme de plusieurs mois de débats souvent tendus, les députés et les sénateurs ont adopté une loi que de nombreux parents attendaient avec impatience. À partir du 1er septembre, les jeunes de moins de 15 ans ne pourraient plus créer de compte sur les réseaux sociaux, et les comptes déjà ouverts devaient être supprimés avant le 1er janvier 2027. La France devenait ainsi le premier pays de l''Union européenne à voter une telle interdiction générale, une décision présentée par ses défenseurs comme un signal fort envoyé aux plateformes.</p><p>Pourtant, la mesure n''est jamais entrée en vigueur. Saisi par des députés, le Conseil constitutionnel l''a censurée le 14 août. Contrairement à ce que certains ont cru comprendre, les juges n''ont pas contesté l''objectif de protéger les adolescents. Ce qu''ils ont reproché au texte, c''est d''aller trop loin. D''abord, il pouvait concerner des services sans danger prouvé pour les jeunes. Ensuite, il limitait la liberté d''expression. Enfin, il obligeait à vérifier l''âge de tous les utilisateurs, adultes compris, sans préciser comment leurs données personnelles seraient protégées.</p><p>Ce dernier point est loin d''être un détail. Pour prouver qu''il a plus de 15 ans, un utilisateur doit bien fournir une information sur son identité, et il faut donc qu''un organisme la conserve, au moins pour un temps. Autrement dit, pour protéger une partie de la population, on risquait de demander à tout le monde de se faire contrôler.</p><p>Une autre partie de la loi, en revanche, a survécu à la décision des juges. Depuis la rentrée 2026, l''interdiction du téléphone portable, qui existait déjà à l''école et au collège, s''applique aussi au lycée. Chaque établissement fixe les règles précises dans son règlement intérieur, ce qui peut expliquer des différences d''un lycée à l''autre.</p><p>Le débat est donc loin d''être clos. Le gouvernement doit présenter un nouveau projet avant le printemps 2027, en tenant compte cette fois des objections du Conseil constitutionnel. De son côté, la Commission européenne prépare un outil commun de vérification de l''âge, sur lequel travaillent sept pays, dont la France. Une solution européenne aurait au moins un avantage : les plateformes ne pourraient plus invoquer la diversité des règles nationales pour ne rien changer. Reste une question, qui est au cœur de toutes les discussions : comment protéger les plus jeunes sans surveiller tout le monde ?</p><p><p><small><em>Texte rédigé par FRACILE à partir de : Toute l''Europe, « Les députés et sénateurs français approuvent l''interdiction de l''accès aux réseaux sociaux pour les moins de 15 ans », 21 juillet 2026 (touteleurope.eu) ; Toute l''Europe, « Pourquoi l''interdiction des réseaux sociaux aux moins de 15 ans reste un casse-tête en France et en Europe », mis à jour le 17 septembre 2026 (touteleurope.eu).</em></small></p></p>' where id = 'lo22mvemxfqj026';
update public.questions q set type = v.type, prompt = v.prompt, payload = v.payload, answer_key = v.answer_key, explanation = v.explanation
from (values
  (1, 'qcm', 'Selon l''article, la loi adoptée en juillet 2026…', '{"options":["ne concernait que les nouveaux téléphones.","visait aussi les comptes déjà existants.","devait s''appliquer dès le 21 juillet."]}'::jsonb, '{"answer":1}'::jsonb, 'Luật không chỉ cấm tạo tài khoản mới: « les comptes déjà ouverts devaient être supprimés avant le 1er janvier 2027 ».'),
  (2, 'vf', 'Avec cette loi, la France était le premier pays de l''Union européenne à voter une interdiction générale de ce type.', '{}'::jsonb, '{"answer":0,"justification":"La France devenait ainsi le premier pays de l''Union européenne à voter une telle interdiction générale"}'::jsonb, null),
  (3, 'qcm', 'Pourquoi le Conseil constitutionnel a-t-il censuré la mesure ?', '{"options":["Il l''a jugée excessive.","Il voulait seulement en retarder l''application.","Il contestait l''idée même de protéger les adolescents."]}'::jsonb, '{"answer":0}'::jsonb, '« Ce qu''ils ont reproché au texte, c''est d''aller trop loin ». Bài nói rõ các thẩm phán « n''ont pas contesté l''objectif de protéger les adolescents ».'),
  (4, 'vf', 'Le texte prévoyait de vérifier l''âge des seuls utilisateurs mineurs.', '{}'::jsonb, '{"answer":1,"justification":"il obligeait à vérifier l''âge de tous les utilisateurs, adultes compris"}'::jsonb, null),
  (5, 'qcm', 'D''après le troisième paragraphe, vérifier l''âge pose problème parce que…', '{"options":["cela oblige à garder des données sur l''identité.","les adolescents mentent souvent sur leur âge.","les plateformes refusent de payer ce contrôle."]}'::jsonb, '{"answer":0}'::jsonb, '« un utilisateur doit bien fournir une information sur son identité, et il faut donc qu''un organisme la conserve ».'),
  (6, 'qcm', 'Que dit l''article de l''interdiction du portable au lycée ?', '{"options":["Ses règles varient selon l''établissement.","Elle a été annulée par les juges.","Elle remplace celle qui existait au collège."]}'::jsonb, '{"answer":0}'::jsonb, '« Chaque établissement fixe les règles précises dans son règlement intérieur ». Phần này « a survécu à la décision des juges », nên không bị huỷ.'),
  (7, 'qcm', 'Quel serait l''intérêt d''un outil européen de vérification de l''âge ?', '{"options":["Il coûterait moins cher que les outils de chaque pays.","Il permettrait d''interdire les réseaux sociaux dans toute l''Europe.","Les plateformes perdraient une excuse pour ne rien faire."]}'::jsonb, '{"answer":2}'::jsonb, '« les plateformes ne pourraient plus invoquer la diversité des règles nationales pour ne rien changer ».'),
  (8, 'qcm', 'Quelle difficulté l''article met-il en avant à la fin ?', '{"options":["convaincre les parents de l''utilité de la mesure","trouver de l''argent pour financer la loi","concilier protection des mineurs et vie privée"]}'::jsonb, '{"answer":2}'::jsonb, 'Câu kết: « comment protéger les plus jeunes sans surveiller tout le monde ? ».')
) as v(ord, type, prompt, payload, answer_key, explanation)
where q.exercise_id = 'lo22mvemxfqj026' and q.ord = v.ord;
